    if (!(s.od > 0)) err(p + 'od', `${n}: OD is required.`);
    if (s.hole_size && s.hole_size <= s.od) err(p + 'hole_size', `${n}: hole size (${s.hole_size}") must be larger than the casing OD (${s.od}").`);
    if (!(s.shoe_md > (s.hanger_md || 0))) err(p + 'shoe_md', `${n}: shoe MD must be below the top of the string.`);
    if (s.toc_md > s.shoe_md) err(p + 'toc_md', `${n}: top of cement (${s.toc_md}) cannot be below the shoe (${s.shoe_md}).`);
    if (s.type === 'liner' && !(s.hanger_md > 0)) err(p + 'hanger_md', `${n}: a liner hangs below surface. Enter the liner top MD.`);
    if (s.type !== 'liner' && s.hanger_md > 0) err(p + 'hanger_md', `${n}: only liners have a top MD; set it to 0 or change the type to liner.`);
    if (s.shoe_md > td) warn(p + 'shoe_md', `${n}: shoe (${s.shoe_md} ft) is below the last survey station (${td} ft); the hole is assumed to continue at the last inclination.`);
    if (!(s.mud_weight > 0)) err(p + 'mud_weight', `${n}: mud weight is required.`);
