    if (i > 0 && s.type !== 'liner' && strings[i - 1].type !== 'liner' && s.od >= strings[i - 1].od) err(p + 'od', `${n}: OD (${s.od}") must be smaller than the string above (${strings[i - 1].od}").`);
    if (i > 0 && s.shoe_md <= strings[i - 1].shoe_md) warn(p + 'shoe_md', `${n}: shoe is not below the previous string's shoe. Check the order of strings.`);
    if (['surface', 'intermediate'].includes(s.type) && (!s.next_hole_mud_weight || !s.next_section_td_md)) warn(p + 'next_hole_mud_weight', `${n}: without "Next section mud weight" and "Next section TD" the lost-returns and kick cases are skipped.`);
    if (s.type === 'production' && !s.frac_surface_pressure && !s.shut_in_tubing_pressure) warn(p + 'frac_surface_pressure', `${n}: no stimulation or tubing-leak pressure, so the production burst cases are skipped.`);
