  for (let i = 0; i <= 200; i++) { const sa = -Y * 2 / Math.sqrt(3) + i * (2 * Y * 2 / Math.sqrt(3)) / 200, disc = Y * Y - 0.75 * sa * sa; if (disc < 0) continue; const root = Math.sqrt(disc); xs.push(sa * area / 1000); up.push((sa / 2 + root) / k); dn.push((sa / 2 - root) / k); }
  const ink = getComputedStyle(document.body).color; const traces = [{x: xs.concat([...xs].reverse()), y: up.concat([...dn].reverse()), mode: 'lines', name: `Triaxial limit / DF ${req}`, line: {color: ink, width: 2}}, {x: [-s.body_yield / 1000, s.tension_rating / 1000, s.tension_rating / 1000, -s.body_yield / 1000, -s.body_yield / 1000], y: [s.burst / r.summary.burst.required, s.burst / r.summary.burst.required, -s.collapse / r.summary.collapse.required, -s.collapse / r.summary.collapse.required, s.burst / r.summary.burst.required], mode: 'lines', name: 'API uniaxial limits / DF', line: {color: '#888', dash: 'dash'}}];
